                         ->get('coupons')
                         ->row();

    if (!$coupon) {
        return ['valid' => false, 'message' => 'Código de cupom não encontrado.'];
    }

    // 1. Verificar se está dentro do período de validade
    $now = date('Y-m-d H:i:s');
