   int last_bar_index = rates_total - 1;

   double currentPrice = price[last_bar_index];   // Preço de fechamento do último candle
   double smaValue = SMABuffer[last_bar_index];  // Valor da SMA no último candle

   // Calcula a distância entre o preço de fechamento e a média
   double distance = MathAbs(currentPrice - smaValue);

   // Verifica se o preço está dentro do intervalo de sensibilidade
   // E se o preço do último candle é diferente do preço do último alerta
   if (distance <= Sensibilidade * _Point && PreviousAlertPrice != currentPrice)
     {
